        try:
            run = subprocess.run(["git", "rev-parse", *argv], capture_output=True, text=True)
        except OSError:
            return found
        out = run.stdout.strip()
        if run.returncode == 0 and out:
            path = pathlib.Path(out)
            path = path.parent if path.name == ".git" else path
            if path not in found:
                found.append(path)
    return found


