// Renders the issue pane with a stand-in for `claude-code`, before any board read and after a good read of no issues, and prints
// `unread: <text>` and `empty: <text>`; usage: bun render-empty-pane.ts
import { plugin } from 'bun'

const state = new Map<string, unknown>()
const h = (type: any, props: any) => ({ type, props: props ?? {} })
const jsx = (type: any, props: any) => h(type, props)
plugin({
  name: 'stand-ins',
  setup(build) {
    build.module('claude-code', () => ({
      exports: {
        atom: (k: { key: string }, init: unknown) => ({ k: k.key, init }),
        read: async (_$: any, a: any) => (state.has(a.k) ? state.get(a.k) : a.init),
        update: async (_$: any, a: any, f: (old: any) => any) => { state.set(a.k, f(state.has(a.k) ? state.get(a.k) : a.init)) },
      },
      loader: 'object',
    }))
    for (const name of ['react/jsx-runtime', 'react/jsx-dev-runtime'])
      build.module(name, () => ({ exports: { jsx, jsxs: jsx, jsxDEV: jsx, Fragment: 'fragment' }, loader: 'object' }))
  },
})

const handlers: Record<string, Function> = {}
const on = (name: string, a: any, b?: any) => {
  handlers[name + ':' + (typeof a === 'object' ? JSON.stringify(a) : '')] = b ?? a
  return { catch: () => undefined }
}
const mod = await import(new URL('../issue-pane.tsx', import.meta.url).pathname)
mod.register(on)

const tags = Object.fromEntries(['Box', 'Text', 'Link', 'Button', 'Markdown'].map(n => [n, n]))
const flat = (n: any): string => Array.isArray(n) ? n.map(flat).join('') : n && typeof n === 'object' ? flat(n.props.children ?? '') : typeof n === 'string' ? n : ''
const $ = {
  plugin: { root: '/x' },
  ui: { resolve: () => tags, open: async () => undefined, panes: async () => [], close: async () => undefined },
  env: { get: async () => '' },
  clock: { after: () => ({ cancel: () => undefined }) },
  process: {
    run: async (argv: string[]) => argv[0].endsWith('list-agents.py')
      ? { exitCode: 0, stdout: 'probe-manager\n', stderr: '' }
      : argv[0].endsWith('list-issue-board.py') ? { exitCode: 0, stdout: '[]', stderr: '' } : { exitCode: 0, stdout: '', stderr: '' },
    spawn: () => (async function* () { yield { text: 'changed' } })(),
  },
}
const render = async () => flat(await handlers['ui.render:{"component":"Pane","requestId":"teamwork-issues"}']($, {}))

console.log(`unread: ${await render()}`)
await handlers['session.start:']($, { cwd: '/tmp' }, async () => ({}))
await new Promise(r => setTimeout(r, 200))
console.log(`empty: ${await render()}`)
